import {storyboardUI} from './storyboard-ui.js';
import {assetUI} from './asset-ui.js';
import {brandMark,newProjectDialog,projectCard as makeProjectCard,blankCards,viewControls} from './project-ui.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={bulb:'<path d="M9 18h6M10 21h4M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 3H9c0-1 0-2-1-3Z"/>',grid:"<rect x=\"3\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\"/>",list:"<path d=\"M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1\"/>",close:"<path d=\"m4 4 16 16M20 4 4 20\"/>",video:"<rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"1\"/><path d=\"m10 9 5 3-5 3Z\"/>",series:"<rect x=\"7\" y=\"7\" width=\"15\" height=\"14\" rx=\"1\"/><path d=\"M16 3H3v13\"/>",more:"<circle cx=\"4\" cy=\"12\" r=\".8\"/><circle cx=\"12\" cy=\"12\" r=\".8\"/><circle cx=\"20\" cy=\"12\" r=\".8\"/>",trash:"<path d=\"M3 6h18M8 6V3h8v3M6 6v15h12V6M10 10v7m4-7v7\"/>",archive:"<rect x=\"3\" y=\"3\" width=\"18\" height=\"5\" rx=\"1\"/><path d=\"M5 8v13h14V8M9 12h6\"/>",edit:"<path d=\"m4 16 12-12 4 4L8 20H4Zm10-10 4 4\"/>",restore:"<path d=\"M4 10a8 8 0 1 1 1 8M4 4v6h6\"/>",home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',folder:'<path d="M3 6h7l2 3h9v11H3Z"/><path d="M3 9V4h7l2 2h9v3"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="m3 16 5-5 4 4 3-3 6 6"/><circle cx="16" cy="8" r="1"/>',settings:'<path d="m10 3-1 3-3 1-3 3 2 3v4l4 1 3 3 3-2h4l1-4 2-3-2-3V6l-4-1-3-2Z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 4v16M4 12h16"/>',film:'<rect x="3" y="3" width="18" height="18" rx="1"/><path d="M7 3v18M17 3v18M3 8h4M3 16h4M17 8h4M17 16h4"/>',script:'<path d="M18 21H5V3h14v14M8 8h8M8 12h8M8 16h4"/>',arrow:'<path d="m5 12 14 0-5-5m5 5-5 5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6"/>',task:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M8 12h8m-8 4h5"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',chevron:'<path d="m8 4 8 8-8 8"/>'};
const icon=n=>`<span class="icon"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]??icons.folder}</svg></span>`;
const state={status:null,projects:[],tasks:[],project:null,episode:null,page:'home',tab:'analysis',dimension:'角色与对象',category:'还原复刻',projectFilter:'all',projectView:'grid',trash:[],trashSelection:[],trashQuery:'',projectSort:'recent',projectQuery:'',dirty:false,saving:false,conflict:false,saveLabel:'只读展示',sequence:0};
let saveTimer,pollTimer,toastTimer;
import {demoApi} from './demo-data.js';
const api=demoApi;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
const date=s=>new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const badge=(text,tone='')=>`<span class="badge ${tone}">${esc(text)}</span>`;
const textItems=v=>Array.isArray(v)?(v.length>1&&v.every(x=>typeof x==='string'&&x.length<=1)?[v.join('')]:v.filter(x=>typeof x==='string'&&x.trim())):typeof v==='string'&&v.trim()?[v]:[];
const activeTask=()=>state.tasks.find(t=>t.episode_id===state.episode?.id&&['queued','running'].includes(t.status));
function shell(content){const on=['project','trash'].includes(state.page)?'projects':state.page;const count=state.tasks.filter(t=>['queued','running'].includes(t.status)).length;$('#app').innerHTML=`<div class="layout page-${esc(state.page)}"><aside class="sidebar"><a href="#home" class="brand"><span class="brand-mark" aria-hidden="true">${brandMark}</span><span>创作工作台</span></a><nav class="nav"><a href="#home" class="${on==='home'?'active':''}">${icon('home')}<span class="desktop-nav-label">工作首页</span><span class="mobile-nav-label">首页</span></a><a href="#projects" class="${on==='projects'?'active':''}">${icon('folder')}<span class="desktop-nav-label">项目中心</span><span class="mobile-nav-label">项目</span></a><a href="#library" class="${on==='library'?'active':''}">${icon('image')}<span class="desktop-nav-label">资产与素材库</span><span class="mobile-nav-label">素材库</span></a></nav><div class="sidebar-bottom"><nav class="nav"><a href="#settings" class="${on==='settings'?'active':''}">${icon('settings')}系统设置</a></nav><div class="local-label"><span class="dot"></span>公开展示 · 示例数据</div></div></aside><main class="main" style="${state.page==='project'&&state.episode?.data.source?`--project-banner:url(/api/episodes/${state.episode.id}/poster)`:''}">${state.page==='project'&&(state.project?.cover||state.episode?.data.source)?`<img class="project-panorama" src="${esc(state.project?.cover||`/api/episodes/${state.episode.id}/poster`)}" alt="">`:''}<header class="topbar"><a class="mobile-brand" href="#home"><span class="brand-mark" aria-hidden="true"></span>创作工作台</a><div class="breadcrumbs">${icon('home')}<a href="#projects">${state.page==='project'?'项目中心':'创作工作台'}</a>${state.project&&state.page==='project'?`<span>/</span><b>${esc(state.project.name)}</b>`:''}</div><div class="topright"><a class="button-link" href="${document.body.classList.contains('mobile-entry')?'./?desktop=1':'./mobile.html'}${location.hash}">${document.body.classList.contains('mobile-entry')?'电脑版':'手机版'}</a><button data-action="tasks">${icon('task')} 任务 <span class="task-count">${count}</span></button><a class="avatar" href="#profile" title="个人中心" aria-label="个人中心">${headerAvatar()}</a></div></header><div class="content">${content}</div></main></div>`;}
function projectCard(p){return makeProjectCard(p,{esc,icon,badge,date});}
function home(){const visibleProjects=state.projects.filter(p=>!p.archived),p=visibleProjects[0],ep=p?.episodes[0];shell(`<div class="welcome"><div><div class="desktop-home-copy"><h1>欢迎回来，${esc(profile.nickname||'张昊')}</h1><p>将心之所向的无边幻境，化作触手可及的眼前之物</p></div><div class="mobile-home-copy"><h1>${esc(profile.nickname||'张昊')}，你好</h1><p>创作，从一个好想法开始。</p></div></div></div><section class="start-card"><div class="start-art" aria-hidden="true"></div><div class="start-copy"><div class="desktop-home-copy"><h2>执笔绘梦，光影成境。</h2><p>起笔是无声的故事，落笔是万千的奇观</p></div><div class="mobile-home-copy"><h2>下一个世界，<br>由你创造。</h2><p>从一个灵感，走向故事与画面。</p></div><button class="primary" data-action="new-project">${icon('plus')} 新建创作</button></div></section><div class="section-head"><h2>继续创作</h2><button class="text" data-action="import-history">导入已有测试结果</button></div>${p?`<section class="resume-card"><a class="resume-cover" href="#project/${p.id}/${ep.id}">${p.cover?`<img src="${esc(p.cover)}" alt="" data-hide-error>`:'<span class="muted">暂无封面</span>'}</a><div class="resume-description"><h3>${esc(p.name)}</h3><p>${p.type==='series'?'系列项目':'单条视频'} · ${esc(ep.stage||'待开始')}</p></div><div class="resume-stages" aria-label="制作阶段：当前处于剧本阶段"><span class="resume-stage active"><i></i>剧本</span><span class="resume-stage"><i></i>资产</span><span class="resume-stage"><i></i>分镜</span></div><a class="button-link" href="#project/${p.id}/${ep.id}">继续创作 ↗</a></section><div class="section-head"><h2>最近项目</h2><a href="#projects">查看全部 ↗</a></div><div class="grid">${visibleProjects.slice(0,3).map(projectCard).join('')+blankCards(Math.max(0,3-visibleProjects.length),{icon})}</div>`:`<div class="empty">${icon('folder')}<h3>还没有项目</h3><p>从一个好想法开始。</p><button class="primary" data-action="new-project">新建项目</button></div>`}<div class="data-note">公开展示 · 示例项目</div>`);}
function projects(){shell(`<div class="welcome"><div><h1>项目中心</h1><p>管理你的作品，继续每一段创作。</p></div><button class="primary" data-action="new-project">${icon('plus')} 新建项目</button></div><div class="project-tools"><label class="search-wrap">${icon('search')}<input class="search" id="project-search" placeholder="搜索项目名称" aria-label="搜索项目" value="${esc(state.projectQuery)}"></label>${viewControls(state.projectView,{icon})}<select id="project-sort" aria-label="项目排序"><option value="recent" ${state.projectSort==='recent'?'selected':''}>最近编辑</option><option value="oldest" ${state.projectSort==='oldest'?'selected':''}>最早创建</option></select></div><div class="project-filters">${[['all','全部'],['single','单条视频'],['series','系列'],['archived','已归档']].map(([key,label])=>`<button data-project-filter="${key}" class="${state.projectFilter===key?'active':''}">${label}</button>`).join('')}</div><div class="grid" id="project-grid"></div><div class="empty search-empty" id="search-empty" hidden>${icon('search')}<h3>没有找到匹配内容</h3><p>请尝试其他关键词或调整筛选。</p><button class="primary" data-action="clear-search">清除筛选</button></div><footer class="projects-footer"><a class="recycle-entry" href="#trash">${icon('trash')}回收站${state.trash.length?' · '+state.trash.length:''}</a></footer>`);renderProjectList();}
function renderProjectList(){const list=state.projects.filter(p=>(state.projectFilter==='archived'?!!p.archived:!p.archived&&(state.projectFilter==='all'||p.type===state.projectFilter))&&p.name.toLowerCase().includes(state.projectQuery.toLowerCase())).sort((a,b)=>state.projectSort==='oldest'?a.created.localeCompare(b.created):b.updated.localeCompare(a.updated));const grid=$('#project-grid'),unfiltered=state.projectFilter==='all'&&!state.projectQuery;grid.className=state.projectView==='grid'?'grid':'project-list';let blanks=0;if(unfiltered)blanks=state.projectView==='grid'?Math.max(6,Math.ceil(list.length/3)*3)-list.length:1;grid.innerHTML=list.map(projectCard).join('')+blankCards(blanks,{icon});$('#search-empty').hidden=unfiltered||!!list.length;document.querySelectorAll('[data-project-filter]').forEach(b=>b.classList.toggle('active',b.dataset.projectFilter===state.projectFilter));document.querySelectorAll('[data-project-view]').forEach(b=>{b.classList.toggle('active',b.dataset.projectView===state.projectView);b.setAttribute('aria-pressed',String(b.dataset.projectView===state.projectView));});bindErrorImages();}
function closeProjectMenus(){document.querySelectorAll('[data-menu]').forEach(menu=>{menu.hidden=true;menu.closest('.project-card')?.classList.remove('menu-open');menu.parentElement.querySelector('[data-more]')?.setAttribute('aria-expanded','false');});}
function showProjectMenu(id){document.querySelectorAll('[data-menu]').forEach(menu=>{const show=menu.dataset.menu===id&&menu.hidden;menu.hidden=!show;menu.closest('.project-card')?.classList.toggle('menu-open',show);const button=menu.parentElement.querySelector('[data-more]');button?.setAttribute('aria-expanded',String(show));});}
function trashPage(){const list=state.trash.filter(p=>p.name.toLowerCase().includes(state.trashQuery.toLowerCase()));state.trashSelection=state.trashSelection.filter(id=>state.trash.some(p=>p.id===id));const selected=state.trashSelection,detail=state.trash.find(p=>p.id===selected[0])??list[0];shell(`<div class="welcome"><div><h1>回收站</h1><p>找回已删除的项目。</p></div><a class="button-link" href="#projects">返回项目中心</a></div>${state.trash.length?`<div class="trash-layout"><section class="panel"><h2>已删除的项目</h2><div class="field"><input id="trash-search" aria-label="搜索已删除的项目" placeholder="搜索已删除的项目" value="${esc(state.trashQuery)}"></div><div class="trash-list"><div class="trash-row head"><input type="checkbox" id="trash-select-all" aria-label="选择全部已删除项目" ${list.length&&list.every(p=>selected.includes(p.id))?'checked':''}><span>项目名称</span><span class="trash-type">类型</span><span>操作</span></div>${list.map(p=>`<div class="trash-row ${selected.includes(p.id)?'selected':''}"><input type="checkbox" data-trash-select="${p.id}" aria-label="选择${esc(p.name)}" ${selected.includes(p.id)?'checked':''}><div class="trash-name"><img src="/api/trash/${p.id}/poster" alt="" data-hide-error><div><strong>${esc(p.name)}</strong><div class="muted">${date(p.deleted_at)}</div></div></div><span class="trash-type">${p.type==='series'?'系列项目':'单条视频'}</span><button class="small" data-restore-project="${p.id}">${icon('restore')}恢复</button></div>`).join('')||'<div class="empty"><p>没有找到匹配内容</p></div>'}</div></section><section class="panel trash-detail"><h2>项目信息</h2>${detail?`<img src="/api/trash/${detail.id}/poster" alt="" data-hide-error><h2>${esc(detail.name)}</h2><p>${detail.type==='series'?'系列项目':'单条视频'} · 删除于 ${date(detail.deleted_at)}</p><div class="divider"></div><h3>项目简介</h3><p>${esc(detail.description||'暂无项目简介')}</p><div class="notice">恢复后，项目将重新出现在项目中心，原有创作内容和版本记录保留。</div>`:''}</section></div><div class="trash-footer"><span>已选 ${selected.length} 个项目</span><button class="primary" data-action="restore-selected" ${selected.length?'':'disabled'}>${icon('restore')}恢复所选</button></div>`:`<div class="empty">${icon('trash')}<h3>回收站是空的</h3><p>移至回收站的项目会保留在这里，可随时恢复。</p><a class="button-link" href="#projects">返回项目中心</a></div>`}`);const all=$('#trash-select-all');if(all)all.indeterminate=list.some(p=>selected.includes(p.id))&&!list.every(p=>selected.includes(p.id));bindErrorImages();}
async function restoreTrash(ids){const projects=ids.map(id=>{const p=state.trash.find(p=>p.id===id);if(!p)throw Error('项目已变化，请刷新');return {id,revision:p.revision};});await api('/api/trash/restore',{method:'POST',body:{projects}});await refreshData();state.trashSelection=[];trashPage();toast('项目已恢复，原内容和历史版本保留');}
function steps(){return `<div class="steps">${['导入与分析','确认分析','故事候选','本集剧本'].map((s,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${i===({analysis:state.episode?.data.analysisConfirmed?1:0,candidates:2,manuscript:3}[state.tab]??0)?'active':''}"><b>${i+1}</b>${s}</span>`).join('')}</div>`;}
const entrySymbols={
 play:'<path d="M9 5.5v13l10-6.5z" fill="currentColor" stroke="none"/>',
 clapper:'<rect x="3" y="6" width="18" height="15" rx="3"/><path d="M3 11h18M7 6l4 5m3-5 4 5"/><path d="m10 13 5 2.5-5 2.5z" fill="currentColor" stroke="none"/>',
 idea:'<path d="M9 18h6m-5 3h4m-5-5c0-3-3-3-3-7a6 6 0 0 1 12 0c0 4-3 4-3 7M12 1V0M4 4 2 2m18 2 2-2M3 9H0m21 0h3"/>',
 feather:'<path d="M3 21 16 8M6 18C4 9 13 3 22 2c-1 8-6 17-16 16zm4-4 1-5m2 2 5-1m-4 5 4-1"/>'
};
const entryIcon=name=>`<span class="icon entry-symbol entry-symbol-${name}"><svg viewBox="0 0 24 24" aria-hidden="true">${entrySymbols[name]}</svg></span>`;
function creationStart(){const p=state.project;shell(`<section class="creation-start"><div class="start-project-heading"><h1>${esc(p.name)} ${badge(p.type==='series'?'系列':'单条视频')}</h1><button data-action="project-info">${icon('settings')} 项目设置</button></div><div class="start-stage-nav"><b>创意与剧本</b><span>资产包</span><span>分镜设计</span></div><header class="start-question"><h2>从哪里开始你的故事？</h2><p>选择一种方式，把你的想法带入创作。</p></header><div class="entry-cards entry-cards-pair">${[
 ['start-reference','entry-reference','play','clapper','参考视频','导入参考视频，分析后开始创作'],
 ['start-inspiration','entry-inspiration','idea','feather','一句话灵感','从一个主题、情节或念头展开']
].map(([action,art,heroSymbol,captionSymbol,title,description])=>`<button class="entry-card" data-action="${action}">
 <span class="entry-art ${art}"><span class="entry-card-title">${entryIcon(heroSymbol)}<strong>${title}</strong></span></span>
 <span class="entry-caption">${entryIcon(captionSymbol)}<span>${description}</span><span class="entry-arrow" aria-hidden="true">→</span></span>
</button>`).join('')}</div></section>`);}
function workspace(){if(state.tab==='start'){creationStart();return;}const p=state.project,e=state.episode,d=e.data,task=activeTask(),mobile=document.body.classList.contains('mobile-entry');shell(`${mobile?'<div class="mobile-project-cover">':'<div class="workspace-header">'}<section class="hero">${p.cover||d.source?`<img class="hero-bg" src="${esc(p.cover||`/api/episodes/${e.id}/poster`)}" alt="">`:''}<div><div class="eyebrow">PROJECT / CREATIVE WORKSPACE</div><h1>${esc(p.name)} ${badge(p.type==='series'?'系列项目':'单条项目')}</h1><p>${esc(p.description||'从参考中提炼方法，用新的故事表达。')}</p></div>${mobile?'</section>':''}<div class="hero-actions"><button data-action="project-cover">项目封面</button><button data-action="project-info">${icon('settings')} 项目设置</button></div>${mobile?'</div><div class="workspace-header">':'</section>'}<div class="work-nav"><div class="toolbar"><select class="episode-select" id="episode-select" aria-label="选择创作内容">${p.episodes.map(ep=>`<option value="${ep.id}" ${ep.id===e.id?'selected':''}>${esc(ep.name)}</option>`).join('')}</select>${p.type==='series'?'<button class="ghost small" data-action="add-episode" title="新增一集">＋</button>':''}</div><div class="tabs"><button class="${!['assets','storyboard'].includes(state.tab)?'active':''}" data-tab="manuscript">${icon('script')}创意与剧本</button><button class="${state.tab==='assets'?'active':''}" data-action="open-assets">${icon('folder')}资产包</button><button class="${state.tab==='storyboard'?'active':''}" data-action="open-storyboard">${icon('film')}分镜设计</button></div><button class="ghost small" data-action="history">${icon('task')}历史</button></div><nav class="creation-subnav" aria-label="创意与剧本步骤"><button class="${state.tab==='analysis'?'active':''}" data-tab="analysis">参考分析</button><button class="${state.tab==='candidates'?'active':''}" data-tab="candidates">故事候选</button><button class="${state.tab==='manuscript'?'active':''}" data-tab="manuscript">本集剧本</button></nav>${task&&state.tab!=='analysis'&&state.tab!=='candidates'?`<div class="notice"><span class="spinner"></span>${esc(task.step)}<span class="muted"> · 关闭页面不取消已提交任务，本机后台须保持运行</span></div>`:''}</div><div class="workspace-body">${state.tab==='analysis'?analysisView():state.tab==='candidates'?((!d.source&&(d.inspiration||state.category==='inspiration'))?inspirationView():candidatesView()):state.tab==='assets'?assets.view():state.tab==='storyboard'?storyboard.view():manuscriptView()}</div><div class="sticky-actions"><span class="save" id="save-state" role="status" aria-live="polite" data-state="saved">${esc(state.saveLabel)}</span><div class="toolbar"><button class="ghost small" data-action="history">查看版本记录</button><div class="save-recovery" id="save-recovery" hidden><button class="small" data-action="save">重试保存</button><button class="small" data-action="copy-current">复制当前内容</button></div><button class="small" data-action="save" ${!state.dirty?'disabled':''}>保存草稿</button></div></div>`);bindErrorImages();}
function analysisProgress(){const t=state.tasks.find(t=>t.episode_id===state.episode?.id&&t.kind==='analyse');if(!t||!['queued','running','partial','failed','completed','interrupted'].includes(t.status))return '';const labels=state.episode?.data.analysis?.continuation?.sourceVerified===false?['准备媒体','内容拆解','创作机制','创作就绪']:['准备媒体','八维拆解','创作机制','证据复核'];let index=/核查|复查|verify/.test(t.step)?3:/机制|修订分析/.test(t.step)?2:/八维/.test(t.step)?1:0;const running=['queued','running'].includes(t.status),done=t.status==='completed'||(!['queued','running'].includes(t.status)&&state.episode?.data.analysis?.continuation?.canContinue);return `<section class="analysis-progress ${running?'is-running':''}" role="status" aria-live="polite"><div class="progress-caption"><strong>${running?'正在分析参考视频':done?'分析已完成':'本次分析未完成'}</strong><span>${running?'后台处理中':done?'结果已保留':'查看任务详情'}</span></div><div class="analysis-nodes">${labels.map((label,i)=>`<div class="analysis-node ${done||i<index?'done':i===index?'current':''}"><i>${done||i<index?'✓':''}</i><span>${label}</span></div>`).join('')}</div><p>${done?'分析内容已就绪，可确认后继续创作':esc(t.step)}${!done&&t.error?' · '+esc(t.error):''}</p><small>${running?'可以继续查看其他页面，请保持本机后台运行。':'任务记录保留了本次处理结果，不会自动重复调用。'}</small></section>`;}
function analysisView(){const e=state.episode,d=e.data,a=d.analysis;const current=state.dimension;if(!state.status.fields[current])state.dimension=Object.keys(state.status.fields)[0];return `<section class="panel analysis-panel"><div class="panel-top"><div><h2>参考视频导入与分析</h2><p>理解它如何吸引观众，确认后再创作。</p></div>${steps()}</div><div class="two-col"><div class="reference-column"><div class="reference-primary"><h3>${icon('video')}参考视频</h3><div class="video-wrap">${d.source?`<video id="reference-video" controls preload="metadata" src="/api/episodes/${e.id}/video"></video>`:`<div class="video-placeholder">${icon('upload')}<p>上传MP4参考视频<br>保留原视频，分析与新创作分别保存</p><button data-action="upload">选择视频</button></div>`}</div>${d.source?`<div class="file-info"><span>${esc(d.source.name)}</span><span>${d.source.duration.toFixed(1)}秒 · ${(d.source.size/1e6).toFixed(1)}MB</span></div>`:''}<input type="file" class="inline-file" id="video-file" accept="video/mp4,.mp4"><div class="toolbar"><button data-action="upload" ${activeTask()?'disabled':''}>${icon('upload')} ${d.source?'替换视频':'上传视频'}</button><button class="primary" data-action="analyse" ${!d.source||activeTask()?'disabled':''}>${a?'重新分析':'开始分析'}</button></div>${analysisProgress()}<div class="status-line">视频上传：最长3分钟、60MB。后台自动压缩与分段分析，保留原视频。</div></div><section class="reference-insights" tabindex="0" aria-label="创作解读滚动区"><h4>创作解读</h4>${a?.creative_mechanism?`<div class="insight"><strong>这条视频，靠什么成立？</strong><p>${esc(a.creative_mechanism.audience_hook)}</p></div><div class="insight"><strong>创作机制</strong><p>${esc(a.creative_mechanism.drivers.map(x=>x.Intention).join('；'))}</p></div>`:''}${a?.origin==='history'?'<div class="notice">已载入历史测试结果，没有重新调用模型。您可以直接对比视频、修改分析并确认。</div>':''}${a?.limitations?.length?`<details class="quality"><summary>分析范围与待注意内容</summary><ul>${textItems(a.limitations).map(l=>`<li>${esc(l)}</li>`).join('')}</ul></details>`:''}</section></div><div tabindex="0" aria-label="分析结果内容滚动区"><div class="section-head" style=""><h3>${icon('script')}分析结果</h3>${a?badge(d.analysisConfirmed?'已有确认版本':a.ready?'待确认':'部分完成',d.analysisConfirmed?'green':a.ready?'':'amber'):badge('等待导入','gray')}</div>${a?`<div class="field"><label for="summary">${icon('script')}一句话故事概括</label><textarea id="summary" class="compact" data-edit="summary">${esc(a.summary)}</textarea></div><div class="dimension-tabs">${Object.keys(state.status.fields).map(dim=>`<button data-dimension="${esc(dim)}" class="${dim===state.dimension?'active':''}">${esc(dim)}</button>`).join('')}</div><div id="dimension-fields">${analysisFields(a)}</div>${!a.ready?`<div class="notice amber">分析还存在关键问题，本轮结果可查看，但不能按正常还原继续生成。<ul class="issue-list">${[...(a.audit?.issues??[]),...(a.dimensionsAudit?.issues??[])].slice(0,8).map(x=>`<li>${esc(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul></div>`:''}<div class="toolbar"><button class="primary" data-action="confirm-analysis" ${!a.ready||activeTask()?'disabled':''}>确认分析，继续创作 ${icon('arrow')}</button></div>`:`<div class="empty">${icon('script')}<h3>等待你的第一条参考视频</h3><p>分析完成后，在这里查看八维拆解、关键证据和创作机制。无法识别的信息会保留为未知。</p></div>`}</div></div></section>`;}
function analysisFields(a){return state.status.fields[state.dimension].map(field=>{const v=a.dimensions?.[state.dimension]?.[field];return `<div class="field"><label>${icon(({'角色与对象':'series','场景与环境':'image','剧情与时间线':'script','镜头与运镜':'film','视觉与光影':'image','声音与文字':'script','剪辑与节奏':'film','提示词与重构':'bulb'})[state.dimension]||'script')}${esc(field)}</label><textarea class="compact" data-edit="observation" data-dim="${esc(state.dimension)}" data-field="${esc(field)}" placeholder="未识别，保留未知">${esc(v?.Observation??'')}</textarea>${v?.Intention?`<div class="help">意图推断：${esc(v.Intention)}${typeof v.confidence==='number'?` · 置信度 ${Math.round(v.confidence*100)}%`:''}</div>`:''}<div class="evidence">${(v?.['Evidence Link']??[]).map(ev=>{const frame=a.manifest.frames.find(f=>f.frame_id===ev.frame_id),time=ev.type==='frame'?frame?.timestamp:ev.start;return typeof time==='number'?`<button data-seek="${time}">${ev.type==='frame'?esc(ev.frame_id):'音画证据'} · ${time.toFixed(1)}s</button>`:'';}).join('')}</div></div>`;}).join('');}
function candidateProgress(){const t=state.tasks.find(t=>t.episode_id===state.episode?.id&&t.kind==='candidates');if(!t)return '';const running=['queued','running'].includes(t.status),done=t.status==='completed';const index=done?3:/修订|修正/.test(t.step)?2:/审查|检查|核对/.test(t.step)?1:0;return `<div class="candidate-progress ${running?'is-running':''}" role="status" aria-live="polite"><div class="analysis-nodes">${['生成故事','一致性审查','自动修订','候选就绪'].map((name,i)=>`<div class="analysis-node ${done||i<index?'done':i===index?'current':''}"><i>${done||i<index?'✓':''}</i><span>${name}</span></div>`).join('')}</div><p>${done?'三个故事已就绪，请选择想继续创作的方向':esc(t.step)}</p></div>`;}
function inspirationView(){
 const d=state.episode.data,idea=d.inspiration||{},task=activeTask();
 const result=d.candidates?.origin==='inspiration'&&d.candidates.ready?d.candidates.draft.candidates:[];
 return `<section class="panel inspiration-panel"><div class="panel-top"><div><h2>一句话灵感</h2><p>写下你想保留的故事设定，再从三个方向中挑一个。</p></div></div>
 <div class="field"><label for="inspiration-idea">你的灵感</label><textarea id="inspiration-idea" rows="4" maxlength="1000" placeholder="例如：父亲想让女儿吃点苦，结果她每换一份工作都干成了行家。">${esc(idea.idea||'')}</textarea></div>
 <div class="inspiration-options"><div class="field"><label for="inspiration-duration">目标时长（秒，选填）</label><input id="inspiration-duration" type="number" min="15" max="180" placeholder="45" value="${esc(idea.duration||'')}"></div>
 <div class="field"><label for="inspiration-style">故事风格（选填）</label><input id="inspiration-style" maxlength="100" placeholder="如轻喜剧" value="${esc(idea.style||'')}"></div></div>
 <div class="toolbar"><button data-action="save-inspiration" ${task?'disabled':''}>保存灵感</button><button class="primary" data-action="generate-inspiration" ${task?'disabled':''}>${result.length?'重新生成三个故事':'生成三个故事'}</button></div>
 ${task?`<p role="status">${esc(task.step)}</p>`:''}
 ${result.length?`<h3>故事候选 · 来自一句话灵感</h3><div class="inspiration-cards">${result.map(choice=>`<article class="panel"><h4>${esc(choice.title)}</h4><p>${esc(choice.hook)}</p><ol>${choice.story_beats.map(beat=>`<li>${esc(beat.action)}${beat.dialogue?`<br>${esc(beat.dialogue)}`:''}</li>`).join('')}</ol><p>结尾 · ${esc(choice.ending)}</p><p>计划 ${choice.planned_duration_seconds} 秒</p><button class="primary" data-select="${esc(choice.id)}" ${task?'disabled':''}>选用并编辑剧本</button></article>`).join('')}</div>`:''}</section>`;
}
async function saveInspiration(generate){
 const idea=$('#inspiration-idea').value.trim();
 const duration=$('#inspiration-duration').value;
 const style=$('#inspiration-style').value.trim();
 if(!idea)throw Error('请先填写一句话灵感');
 await replaceEpisode(await episodeAction('inspiration',{idea,style,duration:duration?Number(duration):45}));
 if(generate)await submitTask('candidates');
 else toast('灵感已保存');
}
function candidatesView(){const d=state.episode.data,c=d.candidates;return `<section class="panel"><div class="panel-top"><div><h2>找到下一段故事的方向</h2><p>沿用参考的创作方法，让故事拥有新的表达。</p></div>${steps()}</div>${!d.analysisConfirmed?'<div class="notice amber">请先在“参考分析”中确认分析，后续创作以确认版本为依据。</div>':''}<div class="category-row">${[['还原复刻','保留核心机制和观看感觉，场景与剧情可以变化。'],['结构创新','借鉴推进结构，设计新的事件和信息安排。'],['表达创新','探索新的表达方法，明确选择哪些机制继续沿用。']].map(([n,t])=>`<button class="category ${n===state.category?'selected':''}" data-category="${n}"><h3>${n}</h3><p>${t}</p></button>`).join('')}</div><div class="section-head candidate-generation-row"><span class="muted">${c?.origin==='history'?'以下为此前模型真实输出，未重新生成。':'每次生成三个可阅读的故事候选。'}</span>${candidateProgress()}<button class="primary" data-action="generate-candidates" ${!d.analysisConfirmed||activeTask()?'disabled':''}>${c?'重新生成三个候选':'生成三个候选'}</button></div>${c?.draft?.candidates?.length?`<div class="candidate-grid">${c.draft.candidates.map((candidate,i)=>`<article class="candidate"><div class="candidate-head"><div class="candidate-index">方案 0${i+1}</div><h3>${esc(candidate.title)}</h3>${candidate.planned_duration_seconds?`<p class="muted">计划 ${esc(candidate.planned_duration_seconds)} 秒 · ${c.narrativeContract?'按参考结构展开':candidate.story_beats.length+'个推进节点'}</p>`:''}<p>${esc(candidate.hook)}</p></div><div class="candidate-body">${candidate.story_beats.map(b=>`<div class="beat"><div class="beat-action">${esc(b.action)}</div><div class="dialogue">${esc(b.dialogue)}</div></div>`).join('')}<div class="beat-action">结尾：${esc(candidate.ending)}</div></div><div class="candidate-footer"><button class="${d.selected?.id===candidate.id?'':'primary'}" data-select="${esc(candidate.id)}" ${!c.ready||!d.analysisConfirmed?'disabled':''}>${d.selected?.id===candidate.id?'已选用 · 打开创作稿':'选择这个故事'}</button></div></article>`).join('')}</div>${c.qualityNotes?.length?`<details class="quality"><summary>保留 ${c.qualityNotes.length} 条质量建议 · 不替代你的创作判断</summary><ul>${c.qualityNotes.map(n=>`<li>${esc(n.reason)}</li>`).join('')}</ul></details>`:''}${!c.ready?`<div class="notice amber">候选部分完成，尚有阻塞问题，暂不能选用。<ul>${(c.issues??[]).map(i=>`<li>${esc(typeof i==='string'?i:JSON.stringify(i))}</li>`).join('')}</ul></div>`:''}`:`<div class="empty">${icon('film')}<h3>三个故事，三种可能</h3><p>确认参考分析、选择创作类别后，生成具体的动作和对白。八维方向随故事一起保存。</p></div>`}</section>`;}
function productionScriptView(m){const p=m.productionScript;if(!p||!Array.isArray(p.scenes)||!Array.isArray(p.assets))return `<div class="notice production-missing">${icon('script')}尚未拆分制作剧本。点击“完善制作剧本”，生成场次、表演与声音、计划时长及资产需求。</div>`;const assets=new Map(p.assets.map(a=>[a.id,a])),name=id=>esc(assets.get(id)?.name||id);return `<section class="production-surface"><div class="production-heading"><div><h2>制作剧本</h2><p>按场次组织，共用人物、场景和道具编号；计划时长尚未配音实测。</p></div><span class="badge">${p.scenes.length} 场 · ${p.assets.length} 项资产 · 计划 ${p.scenes.at(-1)?.end??0} 秒</span></div><div class="production-scenes">${p.scenes.map((s,i)=>`<details class="production-scene" ${i===0?'open':''}><summary><span>${esc(s.id)} · ${esc(s.title)}</span><span>${s.start}–${s.end} 秒</span></summary><div class="production-scene-body"><p class="muted">${icon('image')}${name(s.location_asset_id)} · ${esc(s.time_of_day)}　人物：${(s.character_ids||[]).map(name).join('、')||'无'}</p><p><b>场次目的：</b>${esc(s.purpose)}</p><div class="field"><label>动作过程</label><textarea class="compact" data-edit="production-scene" data-scene="${i}" data-field="action">${esc(s.action)}</textarea></div><div class="field"><label>表演要求</label><textarea class="compact" data-edit="production-scene" data-scene="${i}" data-field="performance">${esc(s.performance)}</textarea></div><h4>对白</h4>${(s.dialogue||[]).map((l,j)=>`<div class="field"><label>${name(l.speaker_id)}</label><textarea class="compact" data-edit="production-scene" data-scene="${i}" data-line="${j}">${esc(l.text)}</textarea></div>`).join('')||'<p class="muted">无对白</p>'}<div class="production-audio"><div><h4>旁白</h4><p>${(s.voiceover||[]).map(v=>esc(v.text)).join('<br>')||'无'}</p></div><div><h4>字幕与画内文字</h4><p>${(s.subtitles||[]).map(v=>`${v.kind==='post'?'后期字幕':'画内文字'}：${esc(v.text)}`).join('<br>')||'无'}</p></div><div><h4>声音设计</h4><p>${(s.sounds||[]).map(v=>`${esc(v.kind)}：${esc(v.description)}`).join('<br>')||'无'}</p></div></div><p class="muted">道具：${(s.prop_ids||[]).map(name).join('、')||'无'} · 关联段落：${(s.source_beat_ids||[]).map(esc).join('、')}</p></div></details>`).join('')}</div><details class="production-assets"><summary>资产需求清单 · ${p.assets.length} 项</summary><div class="production-asset-grid">${p.assets.map(a=>`<article><span class="badge">${{character:'人物',scene:'场景',prop:'道具'}[a.type]} · ${a.required?'必需':'可选'}</span><h4>${esc(a.name)} <small>${esc(a.id)}</small></h4><p>${esc(a.description)}</p><small>使用场次：${p.scenes.filter(s=>s.location_asset_id===a.id||(s.character_ids||[]).includes(a.id)||(s.prop_ids||[]).includes(a.id)).map(s=>esc(s.id)).join('、')||'备用'}</small></article>`).join('')}</div></details>${m.productionAudit?.issues?.length?`<div class="notice">制作检查：${m.productionAudit.issues.map(esc).join('；')}</div>`:''}${m.productionReview?.blocking_issues?.length?`<div class="notice">${m.productionReview.blocking_issues.map(x=>esc(x.reason)).join('；')}</div>`:''}</section>`;}
function manuscriptView(){const d=state.episode.data,m=d.manuscript;if(!m)return `<section class="panel"><div class="empty">${icon('script')}<h3>先选一个想继续讲的故事</h3><p>选定候选后，在这里修改正文、完善制作剧本，并保存确认版本。</p><button data-tab="candidates">查看故事候选</button></div></section>`;return `<section class="panel"><div class="panel-top"><div><h2>${esc(m.title)}</h2><p>${m.expanded?'故事底稿与八维依据已保留，制作剧本用于后续资产与分镜。':'选定故事已保存为草稿，八维当前是方向说明，尚未深化完整制作稿。'}</p></div>${badge(d.manuscriptConfirmed?'已有确认版本':m.expanded?'待确认剧本':'候选深化草稿',d.manuscriptConfirmed?'green':'')}</div><div class="toolbar"><button class="primary" data-action="expand-manuscript" ${activeTask()?'disabled':''}>${m.expanded?'更新制作剧本并检查':'完善制作剧本'}</button>${m.expanded?'<button data-action="review-manuscript">检查当前修改</button>':''}<a href="/api/episodes/${state.episode.id}/export" class="cyan">下载当前草稿 ↓</a></div>${productionScriptView(m)}<div class="divider"></div><div class="two-col"><div class="field"><label for="story-text">故事底稿 · 动作与对白</label><textarea class="editor" id="story-text" data-edit="story">${esc(m.storyText)}</textarea><div class="help">编辑自动保存为新草稿，不自动替换已确认的制作依据。</div></div><div><div class="dimension-tabs">${Object.keys(m.dimensions).map(n=>`<button data-dimension="${esc(n)}" class="${n===state.dimension?'active':''}">${esc(n)}</button>`).join('')}</div><div class="field"><label>${esc(state.dimension)}</label><textarea class="editor" data-edit="manuscript-dimension" data-dim="${esc(state.dimension)}">${esc(typeof m.dimensions[state.dimension]==='string'?m.dimensions[state.dimension]:JSON.stringify(m.dimensions[state.dimension]??'',null,2))}</textarea></div></div></div>${m.review?.blocking_issues?.length?`<div class="notice amber">尚有 ${m.review.blocking_issues.length} 个问题需要解决，结果已保留。<ul>${m.review.blocking_issues.map(i=>`<li>${esc(i.reason)}</li>`).join('')}</ul></div>`:''}${!m.ready?`<div class="notice amber"><strong>暂时无法确认：</strong>${esc((m.productionAudit?.issues?.length?m.productionAudit.issues:m.review?.blocking_issues?.map(i=>i.reason)||[]).join('；')||'需要检查当前修改')}${m.productionAudit?.issues?.length===1&&m.productionAudit.issues[0]==='制作剧本计划时长偏离选定故事'?`<p>当前计划 ${m.productionAudit.plannedDuration} 秒，选定故事目标 ${d.selected?.planned_duration_seconds} 秒。同步只调整计划时间，实际语速将由配音检查。</p><button class="primary" data-action="align-production-timing">同步计划时长并检查</button>`:''}</div>`:''}<div class="toolbar"><button class="primary" data-action="confirm-manuscript" ${!m.expanded||!m.ready||!m.productionScript||!m.productionAudit?.ready||activeTask()?'disabled':''}>确认剧本，进入资产准备 →</button></div>${d.manuscriptConfirmed?'<div class="notice">已保留确认版本，可继续准备人物、场景与道具。<button class="primary" data-action="open-assets">进入资产准备 →</button></div>':''}</section>`;}
const profileKey='workbench-local-profile';
let profile={nickname:'',reduceMotion:false};
try{profile={...profile,...JSON.parse(localStorage.getItem(profileKey)||'{}')};}catch{}
document.body.classList.toggle('profile-reduced-motion',Boolean(profile.reduceMotion));
let avatarUrl='', avatarDraft=null;
function refreshAvatarUrl(){
 if(avatarUrl)URL.revokeObjectURL(avatarUrl);
 avatarUrl='';
 if(typeof profile.avatar==='string'&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(profile.avatar)){
  avatarUrl=URL.createObjectURL(new Blob([Uint8Array.from(atob(profile.avatar.split(',')[1]),c=>c.charCodeAt(0))],{type:'image/jpeg'}));
 }
}
refreshAvatarUrl();
function avatarImage(fallback){
 return avatarUrl?`<img src="${esc(avatarUrl)}" alt="">`:fallback;
}
function headerAvatar(){
 return avatarImage('<span class="icon"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/></svg></span>');
}
async function previewAvatar(file){
 if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('请选择 10 MB 以内的 JPG、PNG 或 WebP 图片');
 const bitmap=await createImageBitmap(file);
 const canvas=document.createElement('canvas');
 canvas.width=canvas.height=256;
 const context=canvas.getContext('2d');
 const edge=Math.min(bitmap.width,bitmap.height);
 context.fillStyle='#192129';
 context.fillRect(0,0,256,256);
 context.drawImage(bitmap,(bitmap.width-edge)/2,(bitmap.height-edge)/2,edge,edge,0,0,256,256);
 bitmap.close();
 avatarDraft=canvas.toDataURL('image/jpeg',.88);
 const preview=$('#avatar-preview');
 if(preview)preview.replaceChildren(canvas);
}
