function settings(){const s=state.status,b=s.budget;shell(`<div class="welcome"><div><div class="eyebrow">WORKSPACE SETTINGS</div><h1>系统设置</h1><p>沿用现有服务配置，密钥保留在后台。</p></div></div><div class="settings-grid"><section class="panel"><h2>模型服务</h2><div class="setting-row"><div><b>视频理解与证据复查</b><p>${esc(s.models.videoModel)}</p></div>${badge(s.models.videoConfigured?'已配置':'未配置',s.models.videoConfigured?'green':'amber')}</div><div class="divider"></div><div class="setting-row"><div><b>文本创作与审查</b><p>${esc(s.models.textModel)}</p></div>${badge(s.models.textConfigured?'已配置':'未配置',s.models.textConfigured?'green':'amber')}</div><div class="divider"></div><div class="setting-row"><div><b>资产图片生成</b><p>${esc(s.models.imageModel)} · 2K · ¥0.20/张</p></div>${badge(s.models.imageKeyConfigured?'密钥已配置 · 待调用验证':'百炼密钥未配置',s.models.imageKeyConfigured?'':'amber')}</div><p class="help">需在百炼北京地域开通Kling Image 3.0。资产包内点击生成时才发起收费请求。</p><div class="setting-row"><div><b>允许本机工作台调用模型</b><p>仅点击生成时调用，遵守原累计测试预算。</p></div><input class="check" type="checkbox" id="ai-toggle" ${s.aiEnabled?'checked':''} aria-label="允许模型调用"></div><div class="notice">默认关闭付费调用。导入已有测试结果、编辑、保存和查看历史不产生模型费用。</div></section><section class="panel"><h2>测试预算</h2><div class="metric">¥ ${b.estimated.toFixed(2)}<small>累计费用估算 / ¥ ${b.limit.toFixed(2)}</small></div><p>历史不确定费用预留：¥ ${b.reserved.toFixed(2)}<br>剩余预算空间：¥ ${b.available.toFixed(2)}</p><div class="notice">每次请求先检查1元保守预留。没有费用凭据的历史请求仍占用预留，不能当作零元。实际账单以服务商为准。</div></section><section class="panel"><h2>保存与运行</h2><p>项目、历史版本和确认版本保存在这台电脑。文字编辑自动保存；未同步草稿另在当前浏览器暂存。</p><p>已提交任务在本机后台继续执行。关闭后台或电脑关机会中断；重启后标为中断，不自动重复付费。</p>${badge('本机单人试用','gray')} ${badge('云端同步尚未接入','gray')}</section><section class="panel"><h2>下一阶段</h2><p>资产管理、图片生成与编辑、单张分镜及完整打包交付，将继续沿用已确认流程接入。</p><p>已接入Kling Image 3.0资产候选图；分镜和视频成片尚未接入。</p><button data-action="import-history">导入已有测试结果</button></section></div>`);}
function library(){shell(`<div class="welcome"><div><div class="eyebrow">ASSET LIBRARY</div><h1>资产与素材库</h1><p>角色、场景与道具，保持每个故事的一致性。</p></div></div><div class="empty">${icon('image')}<h3>资产模块将在下一阶段接入</h3><p>当前先跑通参考分析与创作稿。已确认的人物资产、场景图及逐镜引用规则会沿用，不会用演示素材冒充生成结果。</p><a class="cyan" href="#projects">回到项目中心 →</a></div>`);}
function modal(content,wide=false,variant=''){$('#dialog-root').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''} ${variant}" role="dialog" aria-modal="true">${content}</section></div>`;($('#dialog-root').querySelector('[autofocus]')??$('#dialog-root').querySelector('input:not([type=hidden]),button'))?.focus();}
function closeModal(){$('#dialog-root').innerHTML='';}
async function refreshData(){[state.status,state.projects,state.tasks,state.trash]=await Promise.all([api('/api/status'),api('/api/projects'),api('/api/tasks'),api('/api/trash')]);}
let previousPageHash='#home',lastPageHash=location.hash||'#home';
async function route(){if(state.tab==='storyboard')await storyboard.save();if(state.tab==='assets'){try{await assets.saveDetail();}catch(e){toast(e.message);return;}}if(location.hash!=='#settings')previousPageHash=location.hash||'#home';else if(lastPageHash!=='#settings')previousPageHash=lastPageHash;lastPageHash=location.hash||'#home';try{if(state.dirty||state.saving)await flushSave();const parts=location.hash.slice(1).split('/'),page=parts[0]||'home';state.page=page;state.project=null;state.episode=null;await refreshData();if(page==='project'){state.project=await api('/api/projects/'+parts[1]);const episodeId=parts[2]||state.project.episodes[0].id;state.episode=await api('/api/episodes/'+episodeId);if(!state.project.episodes.some(e=>e.id===episodeId))throw Error('创作内容不属于此项目');state.tab=state.episode.data.source||state.episode.data.analysis?.summary||state.episode.data.manuscript?.storyText?(state.episode.data.inspiration&&!state.episode.data.source?(state.episode.data.manuscript?'manuscript':'candidates'):'analysis'):state.episode.data.inspiration?'candidates':'start';state.category='还原复刻';state.saveLabel='只读展示';state.conflict=false;state.dirty=false;state.sequence=0;workspace();checkLocalDraft();}else if(page==='projects')projects();else if(page==='trash')trashPage();else if(page==='settings')settings();else if(page==='profile')profilePage();else if(page==='library')await assets.library();else{state.page='home';home();}document.querySelectorAll("textarea").forEach(el=>el.readOnly=true);bindErrorImages();window.scrollTo(0,0);}catch(e){toast(e.message);if(state.episode&&state.dirty)return;state.page='home';state.project=null;home();}}
function sizeSummary(){const el=document.getElementById('summary');if(el){el.style.height='auto';el.style.height=el.scrollHeight+2+'px';}}
window.addEventListener('resize',sizeSummary);
function bindErrorImages(){sizeSummary();document.querySelectorAll('[data-hide-error]').forEach(img=>img.addEventListener('error',()=>img.remove(),{once:true}));}
function draftKey(){return 'workbench-draft-'+state.episode.id;}
function markDirty(){state.dirty=true;state.sequence++;state.saveLabel='正在保存…';try{localStorage.setItem(draftKey(),JSON.stringify({revision:state.episode.revision,analysis:state.episode.data.analysis,manuscript:state.episode.data.manuscript,updated:Date.now()}));}catch{state.saveLabel='浏览器草稿暂存失败，正在保存到本机';}updateSaveLabel();clearTimeout(saveTimer);saveTimer=setTimeout(()=>flushSave().catch(()=>{}),750);}
function updateSaveLabel(){const el=$('#save-state');if(el){el.textContent=state.saveLabel;el.classList.toggle('error',state.conflict||state.saveLabel.includes('失败'));el.dataset.state=state.saving||state.saveLabel.includes('正在')?'saving':'saved';const recovery=$('#save-recovery');if(recovery)recovery.hidden=!(state.conflict||state.saveLabel.includes('失败'));}document.querySelector('[data-action="save"]')?.toggleAttribute('disabled',!state.dirty);}
let savePromise=null;
async function flushSave(){clearTimeout(saveTimer);if(savePromise){await savePromise;if(state.dirty&&!state.conflict)return flushSave();return;}if(!state.dirty)return;if(state.conflict)throw Error('有版本冲突，请先保留本地修改并载入最新内容');const episode=state.episode,seq=state.sequence,changes={analysis:structuredClone(episode.data.analysis),manuscript:structuredClone(episode.data.manuscript)};state.saving=true;savePromise=(async()=>{try{const saved=await api('/api/episodes/'+episode.id,{method:'PATCH',body:{revision:episode.revision,changes}});if(state.episode?.id===episode.id){state.episode.revision=saved.revision;state.episode.updated=saved.updated;if(seq===state.sequence)state.episode.data=saved.data;state.dirty=seq!==state.sequence;state.saveLabel=state.dirty?'正在保存…':'只读展示';if(!state.dirty)localStorage.removeItem(draftKey());}}catch(e){state.conflict=e.status===409;state.saveLabel=state.conflict?'版本冲突 · 本地修改已暂存':'保存失败 · 本地修改已暂存';toast(e.message);if(state.conflict)showConflict();throw e;}finally{state.saving=false;savePromise=null;updateSaveLabel();}})();await savePromise;if(state.dirty&&!state.conflict)return flushSave();}
function checkLocalDraft(){try{const raw=localStorage.getItem(draftKey());if(!raw)return;const d=JSON.parse(raw);modal(`<h2>发现未保存的浏览器草稿</h2><p>${date(d.updated)} 暂存的内容尚未写入本机数据库。${d.revision!==state.episode.revision?'数据库版本已变化，请先查看差异，避免覆盖新内容。':''}</p><div class="modal-actions"><button data-action="discard-local">使用已保存版本</button><button class="primary" data-action="restore-local" ${d.revision!==state.episode.revision?'disabled':''}>恢复并保存草稿</button></div>${d.revision!==state.episode.revision?'<button class="text" data-action="download-local">下载本地草稿备份</button>':''}`);}catch{}}
function showConflict(){modal('<h2>内容在另一处更新了</h2><p>你的修改仍保存在当前浏览器，请先下载备份，再重新载入最新内容。不会自动覆盖任何一方。</p><div class="modal-actions"><button data-action="download-local">下载本地草稿</button><button class="primary" data-action="reload-latest">载入最新版本</button></div>');}
async function replaceEpisode(ep){state.episode=ep;state.dirty=false;state.conflict=false;state.saveLabel='只读展示';localStorage.removeItem(draftKey());workspace();}
async function episodeAction(action,body={}){await flushSave();return api(`/api/episodes/${state.episode.id}/${action}`,{method:'POST',body:{...body,revision:state.episode.revision}});}
async function submitTask(kind){await flushSave();if(!state.status.aiEnabled){modal('<h2>模型调用尚未开启</h2><p>您可以先导入已有结果免费体验。若要分析新视频或生成新内容，请在模型设置开启调用；仍受累计测试预算限制。</p><div class="modal-actions"><button data-action="close-modal">稍后</button><button class="primary" data-action="open-settings">打开模型设置</button></div>');return;}await api('/api/tasks',{method:'POST',body:{episodeId:state.episode.id,revision:state.episode.revision,kind,category:kind==='candidates'&&document.querySelector('#inspiration-idea')?'inspiration':state.category==='inspiration'?'还原复刻':state.category,idempotency:crypto.randomUUID()}});state.tasks=await api('/api/tasks');workspace();toast('任务已提交，可继续查看其他页面');}
let taskSelection=[],taskFilter='all',taskLastRemoved=[];
const runningTask=t=>['queued','running'].includes(t.status);
async function clearTaskRecords(ids){if(!ids.length)return;await api('/api/tasks/visibility',{method:'POST',body:{ids}});taskLastRemoved=ids;taskSelection=[];state.tasks=await api('/api/tasks');taskPanel();toast('任务记录已清除，项目结果与费用记录保留');}
async function cancelAssetQueue(body){
 const {changed}=await api('/api/tasks/cancel-images',{method:'POST',body});
 state.tasks=await api('/api/tasks');
 taskPanel();
 toast(changed?`已取消 ${changed} 个排队项，已开始的任务会继续`:'所选任务已开始或结束');
}
function taskPanel(){const list=state.tasks.filter(t=>taskFilter==='active'?runningTask(t):taskFilter==='history'?!runningTask(t):true),eligible=list.filter(t=>!runningTask(t));taskSelection=taskSelection.filter(id=>eligible.some(t=>t.id===id));modal(`<div class="task-panel-heading"><div><h2>任务记录</h2><p>清除列表记录不会删除项目结果、后台文件或费用账目。</p></div><button class="ghost" data-action="close-modal" aria-label="关闭任务记录">${icon('close')}</button></div><div class="task-panel-filters">${[['all','全部'],['active','进行中'],['history','历史记录']].map(([key,label])=>`<button class="${taskFilter===key?'primary':''}" data-action="task-filter" data-filter="${key}">${label} ${state.tasks.filter(t=>key==='active'?runningTask(t):key==='history'?!runningTask(t):true).length}</button>`).join('')}</div><div class="task-bulk"><label><input type="checkbox" id="task-select-all" ${eligible.length&&taskSelection.length===eligible.length?'checked':''} ${!eligible.length?'disabled':''}>全选可清除记录</label><span>已选 ${taskSelection.length} 项</span><button class="small" data-action="task-remove-selected" ${!taskSelection.length?'disabled':''}>清除所选</button><button class="small danger" data-action="task-clear-all" ${!state.tasks.some(t=>!runningTask(t))?'disabled':''}>清空历史</button></div><div class="task-record-list">${list.map(t=>`<article class="task-record"><input type="checkbox" data-task-check="${t.id}" aria-label="选择任务 ${t.id.slice(0,8)}" ${taskSelection.includes(t.id)?'checked':''} ${runningTask(t)?'disabled':''}><div><h3>${esc({analyse:'参考视频分析',candidates:'故事候选',manuscript:'制作剧本','review-manuscript':'剧本审查','asset-image':'资产候选图','project-cover':'项目封面',storyboard:'分镜细化','storyboard-image':'分镜候选图'}[t.kind]||t.kind)} ${(t.asset_name||t.shot_id)?' · '+esc(t.asset_name||t.shot_id):''} ${badge({queued:'排队中',running:'处理中',completed:'已完成',partial:'部分完成',failed:'失败',interrupted:'已中断',cancelled:'已取消'}[t.status],runningTask(t)?'':'gray')}</h3><p class="task-context">${esc(t.project_name)} · ${esc(t.episode_name)}<br>提交：${date(t.created)} · 更新：${date(t.updated)} · 编号 ${esc(t.id.slice(0,8))}</p><p>${esc(t.step)}${t.error?'<br>'+esc(t.error):''}</p></div><div class="task-record-actions">${t.status==='queued'&&t.batch_id?`<button class="small" data-action="cancel-asset-task" data-task-id="${esc(t.id)}">取消此项</button>`:''}${t.batch_id&&list.find(item=>item.batch_id===t.batch_id&&item.status==='queued')?.id===t.id?`<button class="small" data-action="cancel-asset-batch" data-batch-id="${esc(t.batch_id)}">停止本批剩余</button>`:''}<button class="small" data-task="${t.id}">详情</button><button class="small ghost" data-action="task-remove" data-task-id="${t.id}" ${runningTask(t)?'disabled title="进行中的任务不能清除"':''}>${icon('trash')}删除记录</button></div></article>`).join('')||'<div class="empty">暂无任务记录</div>'}</div><div class="task-panel-footer"><span>进行中的任务不可清除</span>${taskLastRemoved.length?'<button class="text" data-action="task-undo">撤销上次清除</button>':''}<button data-action="close-modal">关闭</button></div>`,true,'task-panel');const all=$('#task-select-all');if(all)all.indeterminate=taskSelection.length>0&&taskSelection.length<eligible.length;}
