 'edit-project':async el=>{if(state.dirty||state.saving)await flushSave();const p=state.projects.find(p=>p.id===el.dataset.projectId);if(!p)throw Error('项目已变化，请刷新');modal(`<h2>编辑项目信息</h2><form id="edit-project-form"><input type="hidden" name="id" value="${p.id}"><input type="hidden" name="revision" value="${p.revision}"><div class="field"><label>项目名称</label><input name="name" value="${esc(p.name)}" maxlength="80" required autofocus></div><div class="field"><label>项目简介</label><textarea name="description" maxlength="1000">${esc(p.description)}</textarea></div><div class="modal-actions"><button type="button" data-action="close-modal">取消</button><button class="primary" type="submit">保存修改</button></div></form>`);},
 'archive-project':async el=>{const p=state.projects.find(p=>p.id===el.dataset.projectId);await api('/api/projects/'+p.id,{method:'PATCH',body:{revision:p.revision,changes:{archived:!p.archived}}});await refreshData();state.page==='home'?home():projects();toast(p.archived?'项目已取消归档':'项目已归档，可在“已归档”查看');},
 'trash-project':el=>{const p=state.projects.find(p=>p.id===el.dataset.projectId);modal(`<h2>移至回收站？</h2><p>“${esc(p.name)}”的创作内容和历史版本都会保留，之后可以恢复。</p><div class="modal-actions"><button data-action="close-modal">取消</button><button data-action="confirm-trash" data-project-id="${p.id}">移至回收站</button></div>`);},
 'confirm-trash':async el=>{const p=state.projects.find(p=>p.id===el.dataset.projectId);await api('/api/projects/'+p.id+'/trash',{method:'POST',body:{revision:p.revision}});closeModal();await refreshData();state.page==='home'?home():projects();toast('已移至回收站，可以恢复');},
 'restore-selected':()=>restoreTrash(state.trashSelection),
 'clear-search':()=>{state.projectQuery='';state.projectFilter='all';const input=$('#project-search');if(input)input.value='';renderProjectList();},
 'import-history':async()=>{toast('正在导入真实历史结果，没有调用模型…');const p=await api('/api/import-history',{method:'POST',body:{}});closeModal();location.hash=`project/${p.id}/${p.episodes[0].id}`;},
 'upload':()=>$('#video-file')?.click(),
 'analyse':()=>submitTask('analyse'),
 'generate-candidates':()=>submitTask('candidates'),
 'expand-manuscript':()=>submitTask('manuscript'),
