 'confirm-analysis':async()=>{await replaceEpisode(await episodeAction('confirm-analysis'));state.tab='candidates';workspace();toast('分析确认版本已保存');},
 'align-production-timing':async()=>{await replaceEpisode(await episodeAction('align-production-timing'));toast('计划时长已同步，正文与对白保持不变');},
 'confirm-manuscript':async()=>{await replaceEpisode(await episodeAction('confirm-manuscript'));state.tab='assets';workspace();toast('剧本已确认，请整理资产需求');},
